<?php
 namespace QQWorld\Customer\Test\Constraint; use QQWorld\Catalog\Test\Block\Adminhtml\Product\Edit\Section\AdvancedPricing; use QQWorld\Catalog\Test\Page\Adminhtml\CatalogProductIndex; use QQWorld\Catalog\Test\Page\Adminhtml\CatalogProductNew; use QQWorld\Customer\Test\Fixture\CustomerGroup; use QQWorld\Mtf\Constraint\AbstractConstraint; class AssertCustomerGroupNotOnProductForm extends AbstractConstraint { public function processAssert( CatalogProductIndex $catalogProductIndex, CatalogProductNew $catalogProductNew, CustomerGroup $customerGroup ) { $catalogProductIndex->open(); $catalogProductIndex->getGridPageActionBlock()->addProduct(); $catalogProductNew->getProductForm()->openSection('advanced-pricing'); $advancedPricingTab = $catalogProductNew->getProductForm()->getSection('advanced-pricing'); \PHPUnit_Framework_Assert::assertFalse( $advancedPricingTab->getTierPriceForm()->isVisibleCustomerGroup($customerGroup), "Customer group {$customerGroup->getCustomerGroupCode()} is still in tier price form on product page." ); } public function toString() { return 'Customer group not on product page.'; } } 